// Pre-renders @hackclub/icons (React) to SVG strings so <hc-icon> needs no React.
import { writeFileSync } from 'fs'
import { renderToStaticMarkup } from 'react-dom/server'
import { glyphs } from '@hackclub/icons'

/** Glyphs the components use themselves; always bundled. */
const CORE = [
  'email',
  'github',
  'idea',
  'important',
  'info',
  'instagram',
  'youtube'
]

const header =
  '// Generated by scripts/gen-icons.tsx from @hackclub/icons — do not edit.\n'

const entries = Object.entries(glyphs)
  .filter(([, glyph]) => glyph)
  .map(([name, glyph]) => [name, renderToStaticMarkup(glyph as any)] as const)
  .sort(([a], [b]) => a.localeCompare(b))

const map = (list: typeof entries) =>
  `{\n${list.map(([name, svg]) => `  ${JSON.stringify(name)}: ${JSON.stringify(svg)}`).join(',\n')}\n}`

const write = (file: string, source: string) =>
  writeFileSync(new URL(`../src/${file}`, import.meta.url), header + source)

write(
  'glyph-names.ts',
  `export type GlyphName =\n  | ${entries.map(([name]) => JSON.stringify(name)).join('\n  | ')}

export const glyphNames: GlyphName[] = ${JSON.stringify(entries.map(([name]) => name))}
`
)

write(
  'glyphs.ts',
  `import type { GlyphName } from './glyph-names'

export const glyphs: Record<GlyphName, string> = ${map(entries)}
`
)

write(
  'glyphs-core.ts',
  `export const coreGlyphs: Record<string, string> = ${map(entries.filter(([name]) => CORE.includes(name)))}
`
)

console.log(`Generated ${entries.length} glyphs`)
